plan=json.loads((ROOT/'audit/runs/next-shard-0006-plan.json').read_text(encoding='utf-8'))
assert set(D)==set(plan['questionIds']).intersection(bank)
for qid,(keys,reasons,challenge) in D.items():
    r=review_template(bank[qid])
    r['reviewer']='Codex'
    r['manual']={k:True for k in r['manual']}
    r['notes']='Read final stem/all options; checked full topic/category digests, cross-bank candidate stems and options, category, scope, giveaways and editorial difficulty. '+challenge
    v=r['verification']
    sources=[{'url':S[k][0],'locator':S[k][1]} for k in keys]
    v.update(context=bank[qid]['question'],timeSensitive=False,nextReviewAt=None)
    v['premise']={'reason':reasons[0],'sources':sources}
    v['challenge']={'reviewer':'Codex','at':r['at'],'premiseChecked':True,'alternativesExcluded':True,'notes':challenge}
    for i,o in enumerate(v['options']):
        o.update(reason=reasons[i],sources=sources,basis='direct' if i==0 else 'exclusive-inference')
    if qid in {253,267,274,297}:
        for o in v['options'][1:]: o['basis']='exhaustive-list'
    if qid in {251,252,254,257,262,279,288,290,291}:
        for o in v['options'][1:]: o['basis']='contradiction'
    (OUT/f'{qid}.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(f'Saved {len(D)} final-wording reviews.')
